// qaImgExifOracle is the INDEPENDENT EXIF oracle: it runs exiftool -j -n on the
// fixture (a SEPARATE process invocation from the enricher's) and derives the
// expected sources.image-enricher content by applying the enricher's mapping rules
// independently (ImageWidth->width, FileType->format(lower), DateTimeOriginal->
// RFC3339 UTC, the rest 1:1). Returns nil + error if exiftool is unusable.
func qaImgExifOracle(path string) (map[string]any, error) {
	args := []string{"-j", "-n",
		"-ImageWidth", "-ImageHeight", "-FileType",
		"-Make", "-Model", "-DateTimeOriginal",
		"-Orientation", "-GPSLatitude", "-GPSLongitude",
		path,
	}
	out, err := exec.Command("exiftool", args...).Output()
	if err != nil {
		return nil, err
	}
	var parsed []map[string]any
	if err := json.Unmarshal(out, &parsed); err != nil || len(parsed) == 0 {
		return nil, err
	}
	tags := parsed[0]
	want := map[string]any{}
	if v, ok := qaTagNum(tags, "ImageWidth"); ok {
		want["width"] = v
	}
	if v, ok := qaTagNum(tags, "ImageHeight"); ok {
		want["height"] = v
	}
	if s, ok := tags["FileType"].(string); ok {
		want["format"] = strings.ToLower(s)
	}
	if s, ok := tags["Make"].(string); ok {
		want["make"] = s
	}
	if s, ok := tags["Model"].(string); ok {
		want["model"] = s
	}
	if s, ok := tags["DateTimeOriginal"].(string); ok {
		// Independent re-implementation of normalizeExifDate (enricher.go:192).
		if tm, perr := time.Parse(exifDateLayoutQA, s); perr == nil {
			want["date_taken"] = tm.UTC().Format(time.RFC3339)
		} else {
			want["date_taken"] = s
		}
	}
	if v, ok := qaTagNum(tags, "Orientation"); ok {
		want["orientation"] = v
	}
	if v, ok := qaTagNum(tags, "GPSLatitude"); ok {
		want["gps_lat"] = v
	}
	if v, ok := qaTagNum(tags, "GPSLongitude"); ok {
		want["gps_lon"] = v
	}
	return want, nil
}

// qaTagNum reads a numeric tag from exiftool's JSON (numbers decode to float64).
func qaTagNum(tags map[string]any, k string) (float64, bool) {
	switch n := tags[k].(type) {
	case float64:
		return n, true
	case int:
		return float64(n), true
	}
	return 0, false
}

// qaImgNum reads a JSON numeric namespace field (structpb emits float64).
func qaImgNum(m map[string]any, k string) (float64, bool) {
	switch n := m[k].(type) {
	case float64:
		return n, true
	case int:
		return float64(n), true
	}
	return 0, false
}

func qaImgAbs(f float64) float64 {
	if f < 0 {
		return -f
	}
	return f
}

// qaImgFixtures describes the QA fixture library: root, the discovered image
// relative paths, the EXIF JPEG path (for the oracle), and the HEIC rel ("" if
// sips could not produce one).
type qaImgFixtures struct {
	root    string
	rels    []string
	exifJPG string
	heicRel string
}

// qaImgWriteFixtures builds the QA image fixture tree with DIFFERENT filenames and
// EXIF from the coder golden: an EXIF-rich Canon JPEG, an EXIF-less PNG, a HEIC
// (when sips is available), a DIFFERENT Cyrillic-named JPEG (non-ASCII Model), a
// truncated JPEG, and a stray .mp4 (must NOT be discovered). JPEG/PNG are
// stdlib-encoded; EXIF is stamped by the real exiftool (arg-slice only); HEIC by
// sips. All image files are real on-disk files.
func qaImgWriteFixtures(t *testing.T) qaImgFixtures {
	t.Helper()
	root := t.TempDir()
	fx := qaImgFixtures{root: root}

	fx.exifJPG = filepath.Join(root, "DSC_5082.jpg")
	qaImgEncode(t, fx.exifJPG, qaImgEXIFW, qaImgEXIFH, "jpeg")
	qaImgStampEXIF(t, fx.exifJPG, qaImgMake, qaImgModel, qaImgDT, qaImgOrient, qaImgGPSLat, qaImgGPSLon)
	fx.rels = append(fx.rels, "DSC_5082.jpg")

	qaImgEncode(t, filepath.Join(root, "scan.png"), qaImgPNGW, qaImgPNGH, "png")
	fx.rels = append(fx.rels, "scan.png")

	if rel, ok := qaImgGenHEIC(t, root, "pixel.heic", 48, 48); ok {
		fx.rels = append(fx.rels, rel)
		fx.heicRel = rel
	}

	cyr := filepath.Join(root, "Снимок.jpg")
	qaImgEncode(t, cyr, 56, 56, "jpeg")
	qaImgStampEXIF(t, cyr, qaImgMake, qaImgCyrillicModel, qaImgDT, qaImgOrient, qaImgGPSLat, qaImgGPSLon)
	fx.rels = append(fx.rels, "Снимок.jpg")

	mustWrite(t, filepath.Join(root, "broken.jpg"), []byte("\xff\xd8\xff\xe0TRUNCATED"))
	fx.rels = append(fx.rels, "broken.jpg")

	mustWrite(t, filepath.Join(root, "trailer.mp4"), []byte("not a video"))
	return fx
}

// qaImgEncode encodes a solid WxH image at path via the stdlib jpeg or png encoder.
func qaImgEncode(t *testing.T, path string, w, h int, format string) {
	t.Helper()
	f, err := os.Create(path)
	if err != nil {
		t.Fatalf("create %s: %v", filepath.Base(path), err)
	}
	defer f.Close()
	img := qaImgSolid(w, h)
	if format == "png" {
		if err := png.Encode(f, img); err != nil {
			t.Fatalf("png encode %s: %v", filepath.Base(path), err)
		}
		return
	}
	if err := jpeg.Encode(f, img, &jpeg.Options{Quality: 50}); err != nil {
		t.Fatalf("jpeg encode %s: %v", filepath.Base(path), err)
	}
}

// qaImgSolid returns a solid opaque WxH RGBA image (pixel color is irrelevant;
// exiftool/stdlib read the header/dims).
func qaImgSolid(w, h int) *image.RGBA {
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for i := 0; i < len(img.Pix); i += 4 {
		img.Pix[i] = 180
		img.Pix[i+1] = 120
		img.Pix[i+3] = 255
	}
	return img
}

// qaImgStampEXIF stamps real exiftool EXIF tags onto a JPEG (arg-slice ONLY, NEVER
// a shell). -n forces numeric values. Mirrors the enricher's own exiftool shape.
func qaImgStampEXIF(t *testing.T, path, make, model, dt string, orient int, lat, lon float64) {
	t.Helper()
	args := []string{
		"-overwrite_original", "-q", "-n",
		"-Make=" + make,
		"-Model=" + model,
		"-DateTimeOriginal=" + dt,
		"-Orientation=" + strconv.Itoa(orient),
		"-GPSLatitude=" + strconv.FormatFloat(lat, 'f', -1, 64),
		"-GPSLongitude=" + strconv.FormatFloat(lon, 'f', -1, 64),
		path,
	}
	if out, err := exec.Command("exiftool", args...).CombinedOutput(); err != nil {
		t.Fatalf("exiftool stamp %s: %v: %s", filepath.Base(path), err, out)
	}
}

// qaImgGenHEIC generates a WxH HEIC via macOS sips. Returns ("", false) when sips
// is unavailable — the HEIC sub-case is then skipped.
func qaImgGenHEIC(t *testing.T, root, name string, w, h int) (string, bool) {
	t.Helper()
	if _, err := exec.LookPath("sips"); err != nil {
		t.Logf("sips not on PATH — skipping HEIC fixture %q", name)
		return "", false
	}
	src := filepath.Join(root, ".heic-src.jpg")
	qaImgEncode(t, src, w, h, "jpeg")
	path := filepath.Join(root, name)
	out, err := exec.Command("sips", "-s", "format", "heic", src, "--out", path).CombinedOutput()
	_ = os.Remove(src)
	if err != nil {
		t.Logf("sips heic %s unavailable: %v: %s — skipping", name, err, out)
		return "", false
	}
	if info, e := os.Stat(path); e != nil || info.Size() == 0 {
		return "", false
	}
	return name, true
}

// qaImgCreateLibrary POSTs an IMAGE library (module_id=image) and returns its id.
func qaImgCreateLibrary(t *testing.T, c *http.Client, baseURL, token, root string) int64 {
	t.Helper()
	body := struct {
		ModuleID    string `json:"module_id"`
		RootPath    string `json:"root_path"`
		DisplayName string `json:"display_name"`
	}{ModuleID: "image", RootPath: root, DisplayName: "QA Image"}
	var resp libraryResponse
	status := doRequest(t, c, http.MethodPost, baseURL+"/api/v1/libraries", token, body, &resp)
	if status != http.StatusCreated {
		t.Fatalf("create image library: HTTP %d, want 201", status)
	}
	return resp.ID
}

// qaImgWaitForReady polls until every rel is 'ready' (bounded; INV-poll-bounded).
func qaImgWaitForReady(t *testing.T, c *http.Client, baseURL string, libID int64, rels []string) map[string]itemDTO {
	t.Helper()
	deadline := time.Now().Add(qaImgDrainTimeout)
	for time.Now().Before(deadline) {
		byRel := indexByPath(t, listItems(t, c, baseURL, qaImgToken, libID))
		if qaImgAllReady(byRel, rels) {
			return byRel
		}
		time.Sleep(probeInterval)
	}
	byRel := indexByPath(t, listItems(t, c, baseURL, qaImgToken, libID))
	t.Fatalf("QA image drain did not settle %v to ready within %s; last: %s", rels, qaImgDrainTimeout, qaImgStatuses(byRel))
	return byRel
}

// qaImgPollListable waits for both items to be listable, then gives the worker a
// short window to attempt + soft-fail before snapshotting. Used by the
// exiftool-missing test, which must NOT hard-assert ready (no_data cooldown timing
// is non-deterministic).
func qaImgPollListable(t *testing.T, c *http.Client, baseURL string, libID int64) map[string]itemDTO {
	t.Helper()
	deadline := time.Now().Add(10 * time.Second)
	for time.Now().Before(deadline) {
		if len(indexByPath(t, listItems(t, c, baseURL, qaImgToken, libID))) >= 2 {
			break
		}
		time.Sleep(probeInterval)
	}
	time.Sleep(3 * time.Second) // let the worker attempt + soft-fail (no_data path)
	return indexByPath(t, listItems(t, c, baseURL, qaImgToken, libID))
}

func qaImgAllReady(byRel map[string]itemDTO, rels []string) bool {
	for _, rel := range rels {
		it, ok := byRel[rel]
		if !ok || it.Status != "ready" {
			return false
		}
	}
	return true
}

func qaImgStatuses(byRel map[string]itemDTO) string {
	out := make([]string, 0, len(byRel))
	for rel, it := range byRel {
		out = append(out, rel+"="+it.Status)
	}
	sort.Strings(out)
	return strings.Join(out, " ")
}

// qaImgStrippedPath builds a temp PATH directory containing symlinks to ffprobe +
// ffmpeg ONLY (no exiftool), and returns its absolute path. The server + plugins
// are launched via absolute env paths (MELLIFERA_*), so they need no PATH entry;
// base-scanner's ffprobe fallback resolves via this stripped PATH; image-enricher's
// exec.LookPath("exiftool") fails here. Skips if ffprobe/ffmpeg are absent.
func qaImgStrippedPath(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	for _, tool := range []string{"ffprobe", "ffmpeg"} {
		bin, err := exec.LookPath(tool)
		if err != nil {
			t.Skipf("%s not on PATH — cannot build stripped PATH for exiftool-missing sim", tool)
		}
		if err := os.Symlink(bin, filepath.Join(dir, tool)); err != nil {
			t.Fatalf("symlink %s: %v", tool, err)
		}
	}
	return dir
}

// qaImgStartServerStrippedPath starts the server with PATH=<stripped> (containing
// ffprobe/ffmpeg but NOT exiftool), so the image-enricher subprocess inherits a
// PATH where exec.LookPath("exiftool") fails. Otherwise identical to startServer.
func qaImgStartServerStrippedPath(t *testing.T, serverBin, scannerBin, tvParserBin, imageEnricherBin, tmp, token, pathDir string) string {
	t.Helper()
	addr := net.JoinHostPort("127.0.0.1", freePort(t))
	dataDir := filepath.Join(tmp, "data-miss")

	// Build the env WITHOUT the inherited PATH (filter it), then add the stripped
	// PATH + the plugin/server vars. Filtering avoids last-wins duplicate-key ambiguity.
	env := make([]string, 0, len(os.Environ())+8)
	for _, kv := range os.Environ() {
		if strings.HasPrefix(kv, "PATH=") {
			continue
		}
		env = append(env, kv)
	}
	env = append(env,
		"PATH="+pathDir,
		"MELLIFERA_DATA_DIR="+dataDir,
		"MELLIFERA_ADMIN_TOKEN="+token,
		"MELLIFERA_BASE_SCANNER="+scannerBin,
		"MELLIFERA_TV_PARSER="+tvParserBin,
		"MELLIFERA_IMAGE_ENRICHER="+imageEnricherBin,
		"MELLIFERA_LISTEN="+addr,
	)

	srv := exec.Command(serverBin)
	srv.Env = env
	var log strings.Builder
	srv.Stdout = &log
	srv.Stderr = &log
	if err := srv.Start(); err != nil {
		t.Fatalf("start server (stripped PATH): %v", err)
	}
	baseURL := "http://" + addr
	t.Cleanup(func() { stopServer(t, srv, &log) })
	if !waitForReady(baseURL) {
		t.Fatalf("server not ready at %s within %s; log:\n%s", baseURL, readinessDial, log.String())
	}
	return baseURL
}
